-- Apply after 20261016_traffic_ingestion_receipts.sql and before the new app starts.
-- Keep a database backup. Duplicate signal rows are archived as JSON before consolidation.
BEGIN;

ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_version BIGINT NOT NULL DEFAULT 0;

ALTER TABLE traffic_data ADD COLUMN IF NOT EXISTS event_id VARCHAR(64);
ALTER TABLE traffic_data ADD COLUMN IF NOT EXISTS payload_hash VARCHAR(64);
CREATE UNIQUE INDEX IF NOT EXISTS uq_traffic_data_event_id ON traffic_data(event_id);

-- Historical results were generated by a simulation, not an integrated trained model.
UPDATE traffic_predictions SET model_version='SIMULATION-legacy', confidence=NULL
WHERE model_version LIKE 'LSTM%';

ALTER TABLE traffic_signals ADD COLUMN IF NOT EXISTS candidate_green_duration INTEGER;
ALTER TABLE traffic_signals ADD COLUMN IF NOT EXISTS candidate_yellow_duration INTEGER;
ALTER TABLE traffic_signals ADD COLUMN IF NOT EXISTS candidate_cycle_duration INTEGER;
ALTER TABLE traffic_signals ADD COLUMN IF NOT EXISTS candidate_strategy VARCHAR(20);

CREATE TABLE IF NOT EXISTS traffic_signal_duplicate_archive (
    original_id BIGINT PRIMARY KEY,
    archived_row JSONB NOT NULL,
    archived_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
WITH ranked AS (
    SELECT id, row_number() OVER (
        PARTITION BY intersection_id, direction ORDER BY updated_at DESC NULLS LAST, id DESC
    ) AS position FROM traffic_signals
)
INSERT INTO traffic_signal_duplicate_archive(original_id, archived_row)
SELECT s.id, to_jsonb(s) FROM traffic_signals s JOIN ranked r ON r.id=s.id
WHERE r.position > 1 ON CONFLICT (original_id) DO NOTHING;

WITH ranked AS (
    SELECT id, row_number() OVER (
        PARTITION BY intersection_id, direction ORDER BY updated_at DESC NULLS LAST, id DESC
    ) AS position FROM traffic_signals
)
DELETE FROM traffic_signals s USING ranked r WHERE s.id=r.id AND r.position > 1;
CREATE UNIQUE INDEX IF NOT EXISTS uq_signal_intersection_direction
    ON traffic_signals(intersection_id, direction);

ALTER TABLE traffic_alerts ADD COLUMN IF NOT EXISTS active_key VARCHAR(160);
ALTER TABLE traffic_alerts ADD COLUMN IF NOT EXISTS direction VARCHAR(20);
ALTER TABLE traffic_alerts ADD COLUMN IF NOT EXISTS source VARCHAR(20);
ALTER TABLE traffic_alerts ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMP;
UPDATE traffic_alerts SET source='LEGACY' WHERE source IS NULL;
UPDATE traffic_alerts SET last_seen_at=created_at WHERE last_seen_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_alert_active_key ON traffic_alerts(active_key);
CREATE INDEX IF NOT EXISTS idx_alert_condition_history
    ON traffic_alerts(source, intersection_id, direction, last_seen_at);

CREATE INDEX IF NOT EXISTS idx_traffic_latest_direction
    ON traffic_data(intersection_id, direction, record_time DESC, id DESC);

ALTER TABLE route_plans ADD COLUMN IF NOT EXISTS algorithm VARCHAR(30);
ALTER TABLE route_plans ADD COLUMN IF NOT EXISTS traffic_data_status VARCHAR(20);
ALTER TABLE route_plans ADD COLUMN IF NOT EXISTS sampled_intersection_count INTEGER;
ALTER TABLE route_plans ADD COLUMN IF NOT EXISTS sampled_direction_count INTEGER;
COMMIT;
